-- Account kinds for new actions; historical attribution remains unchanged.
ALTER TABLE AUD_PIPELINES_RUN_LOG ADD COLUMN WRITER VARCHAR(128) NOT NULL DEFAULT 'etl-craft' CONSTRAINT ck_run_writer CHECK (length(trim(WRITER)) BETWEEN 1 AND 128);
ALTER TABLE AUD_PIPELINES_RUN_LOG DROP CONSTRAINT ck_aud_pipelines_run_log_started_by_kind;
ALTER TABLE AUD_PIPELINES_RUN_LOG ADD CONSTRAINT ck_aud_pipelines_run_log_started_by_kind CHECK (STARTED_BY_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
ALTER TABLE AUD_PIPELINES_RUN_LOG DROP CONSTRAINT ck_aud_pipelines_run_log_ended_by_kind;
ALTER TABLE AUD_PIPELINES_RUN_LOG ADD CONSTRAINT ck_aud_pipelines_run_log_ended_by_kind CHECK (ENDED_BY_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
ALTER TABLE AUD_RUN_INTERVENTIONS DROP CONSTRAINT ck_aud_run_interventions_requested_by_kind;
ALTER TABLE AUD_RUN_INTERVENTIONS ADD CONSTRAINT ck_aud_run_interventions_requested_by_kind CHECK (REQUESTED_BY_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
ALTER TABLE AUD_PIPELINE_PAUSES DROP CONSTRAINT ck_aud_pipeline_pauses_paused_by_kind;
ALTER TABLE AUD_PIPELINE_PAUSES ADD CONSTRAINT ck_aud_pipeline_pauses_paused_by_kind CHECK (PAUSED_BY_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
ALTER TABLE AUD_PIPELINE_PAUSES DROP CONSTRAINT ck_aud_pipeline_pauses_resumed_by_kind;
ALTER TABLE AUD_PIPELINE_PAUSES ADD CONSTRAINT ck_aud_pipeline_pauses_resumed_by_kind CHECK (RESUMED_BY_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
ALTER TABLE AUD_TASK_ATTEMPTS DROP CONSTRAINT ck_aud_task_attempts_requested_by_kind;
ALTER TABLE AUD_TASK_ATTEMPTS ADD CONSTRAINT ck_aud_task_attempts_requested_by_kind CHECK (REQUESTED_BY_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
ALTER TABLE AUD_ACTIONS DROP CONSTRAINT ck_actions_actor_kind;
ALTER TABLE AUD_ACTIONS ADD CONSTRAINT ck_actions_actor_kind CHECK (ACTOR_KIND IN ('USER','SERVICE','SYSTEM','HUMAN','SCHEDULE','ORCHESTRATOR','WORKER'));
